steps.command:
git init -q
echo '{ "type": "module", "scripts": { "test": "node --test" } }' > package.json
echo 'export const slugify = (text) => text.toLowerCase();' > slug.js
cat > slug.test.js <<'END'
import test from "node:test";
import assert from "node:assert/strict";
import { slugify } from "./slug.js";
test("lowercases", () => assert.equal(slugify("Hello"), "hello"));
END
git add -A && git -c user.name=demo -c user.email=demo@example.com commit -qm "start"

steps.stdout:
 M slug.js
 M slug.test.js
diff --git a/slug.js b/slug.js
index e3612b2..9941cc4 100644
--- a/slug.js
+++ b/slug.js
@@ -1 +1 @@
-export const slugify = (text) => text.toLowerCase();
+export const slugify = (text) => text.toLowerCase().replace(/ +/g, "-");
diff --git a/slug.test.js b/slug.test.js
index ceb094e..bc10b42 100644
--- a/slug.test.js
+++ b/slug.test.js
@@ -2,3 +2,4 @@ import test from "node:test";
 import assert from "node:assert/strict";
 import { slugify } from "./slug.js";
 test("lowercases", () => assert.equal(slugify("Hello"), "hello"));
+test("replaces runs of spaces with a single dash", () => assert.equal(slugify("hello   world"), "hello-world"));
